import React, { useEffect, useState } from 'react';

const lines = [
  ['name', '=', '"Chetanya Makkar"'],
  ['major', '=', '"Computer Science"'],
  ['minor', '=', '"Computational Finance"'],
  ['gpa', '=', '3.76'],
  ['school', '=', '"University of Maryland"']
];

export default function App() {
  const [visibleLines, setVisibleLines] = useState([]);
  const [typingIndex, setTypingIndex] = useState(-1);
  const [loop, setLoop] = useState(0);

  useEffect(() => {
    let i = 0;
    setVisibleLines([]);
    setTypingIndex(-1);

    const interval = setInterval(() => {
      if (i < lines.length) {
        setTypingIndex(i);
        setVisibleLines((prev) => [...prev, lines[i]]);
        i++;
      }

      if (i === lines.length) {
        clearInterval(interval);
        setTimeout(() => setLoop((l) => l + 1), 2500);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [loop]);

  return (
    <div className="bg-[#1e1e1e] text-[#d4d4d4] min-h-screen flex items-center justify-center font-mono text-xl p-6">
      <div className="space-y-2 text-left">
        {visibleLines.map((tokens, idx) => {
          if (!Array.isArray(tokens) || tokens.length < 3) return null;

          const isTyping = idx === typingIndex && idx !== lines.length - 1;

          return (
            <div
              key={`${loop}-${idx}`}
              className={`overflow-hidden whitespace-nowrap min-w-[12ch] ${
                isTyping ? 'animate-typing border-r-2 border-gray-400' : ''
              }`}
            >
              <span className="text-[#9CDCFE]">{tokens[0]}</span>
              <span className="text-[#d4d4d4]"> {tokens[1]} </span>
              <span className={tokens[2]?.includes('"') ? 'text-[#ce9178]' : 'text-[#b5cea8]'}>
                {tokens[2]}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
